CREATE (n:Estado { ibge:12, nome:'Acre', sigla : 'AC' }); (m:Municipio { ibge:120001, nome:'Acrelandia' , uf:12}); CREATE (o:Municipio { ibge:120005, nome:'Assis Brasil' , uf:12});

